declare_rule! {
    /// Disallow the use of `console`.
    ///
    /// In a production environment, it's not recommended to have `console` calls.
    /// It's expected that most of them are leftovers from debugging, and they should
    /// be removed before shipping code to production.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// console.error('hello world')
    /// ```
    ///
    pub(crate) NoConsole {
        version: "next",
        name: "noConsole",
